package com.smartbi.query;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import java.net.*;import java.util.*;import java.util.stream.Collectors;
@Component public class JdbcUrlPolicy{
 private final Set<String> allowedHosts;private final Set<Integer> allowedPorts;
 public JdbcUrlPolicy(@Value("${smartbi.network.allowed-hosts:}")String hosts,@Value("${smartbi.network.allowed-ports:5432}")String ports){allowedHosts=Arrays.stream(hosts.split(",")).map(String::trim).filter(s->!s.isEmpty()).map(s->IDN.toASCII(s).toLowerCase(Locale.ROOT)).collect(Collectors.toUnmodifiableSet());try{allowedPorts=Arrays.stream(ports.split(",")).map(String::trim).filter(s->!s.isEmpty()).map(Integer::valueOf).collect(Collectors.toUnmodifiableSet());}catch(RuntimeException e){throw new IllegalArgumentException("Invalid smartbi.network.allowed-ports",e);}}
 public void validatePostgreSql(String jdbcUrl){if(jdbcUrl==null||!jdbcUrl.startsWith("jdbc:postgresql://"))invalid();try{URI uri=URI.create(jdbcUrl.substring(5));String host=uri.getHost();int port=uri.getPort()<0?5432:uri.getPort();if(!"postgresql".equals(uri.getScheme())||host==null||uri.getRawUserInfo()!=null||uri.getRawQuery()!=null||uri.getRawFragment()!=null||uri.getPath()==null||!uri.getPath().matches("/[A-Za-z0-9_.-]+"))invalid();host=IDN.toASCII(host).toLowerCase(Locale.ROOT);if(!allowedHosts.contains(host)||!allowedPorts.contains(port))throw new QueryException("DATASOURCE_URL_FORBIDDEN","Data source host or port is not allow-listed");}catch(QueryException e){throw e;}catch(RuntimeException e){invalid();}}
 private static void invalid(){throw new QueryException("DATASOURCE_URL_INVALID","A canonical PostgreSQL JDBC URL without user-info, fragments, or connection parameters is required");}
}
